final class BinarySearch {
    private static final int NOT_FOUND = -1;
    private static final String FOUND_MESSAGE = "Element is present at index ";
    private static final String NOT_FOUND_MESSAGE = "Element is not present in array";

    private BinarySearch() {
    }

    static int binarySearch(int[] sortedNumbers, int target) {
        int low = 0;
        int high = sortedNumbers.length - 1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            int current = sortedNumbers[mid];

            if (current == target) {
                return mid;
            }

            if (current < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return NOT_FOUND;
    }

    public static void main(String[] args) {
        int[] numbers = { 2, 3, 4, 10, 40 };
        int target = 10;

        int result = binarySearch(numbers, target);
        if (result == NOT_FOUND) {
            System.out.println(NOT_FOUND_MESSAGE);
        } else {
            System.out.println(FOUND_MESSAGE + result);
        }
    }
}

